        q=np.frombuffer(memoryview(b)[k:k+(len(b)-k)//4*4],dtype='<u4'); matches=(q[:-2]<n)&(q[1:-1]==q[2:])
        for x in np.flatnonzero(matches).tolist():ret[int(q[x])].append((4*x+k,int(q[x+1])))
